package jp.tapmarker;
import java.io.*;import java.util.*;
public class CircuitPolicyTest {
 static int checks=0;static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 static ScreenPolicy.Example example(float[] raw,float[] embedding,int action){ScreenPolicy.Example e=new ScreenPolicy.Example();e.pkg="target.app";e.width=1080;e.height=2400;e.action=action;e.raw=raw;e.embedding=embedding;return e;}
 public static void main(String[] args)throws Exception{
 FlyCircuit c=new FlyCircuit(new FileInputStream(args[0]));check(c.n==8795&&c.w.length==142482&&c.output.length==104,"actual circuit dimensions");float[] a=new float[768],b=new float[768],unknown=new float[768];Arrays.fill(a,.5f);Arrays.fill(b,.55f);Arrays.fill(unknown,.9f);long t=System.nanoTime();float[] za=c.encode(a),zb=c.encode(b);System.out.println("Two-image JVM circuit runtime ms="+(System.nanoTime()-t)/1e6);check(FlyCircuit.distance(za,c.encode(a))==0,"deterministic image encoding");check(FlyCircuit.distance(za,zb)>1e-9,"different images affect circuit output");float[] weights=c.w.clone();Arrays.fill(c.w,0);float[] ablated=c.encode(b);System.arraycopy(weights,0,c.w,0,weights.length);check(FlyCircuit.distance(zb,ablated)>1e-9,"removing graph changes output");for(float v:zb)checkFinite(v);check(true,"finite circuit output");ArrayList<ScreenPolicy.Example> examples=new ArrayList<>();examples.add(example(a,za,0));examples.add(example(b,zb,2));check(ScreenPolicy.select(examples,"target.app",1080,2400,a,za)==0,"known screen selects taught tap");check(ScreenPolicy.select(examples,"target.app",1080,2400,b,zb)==1,"other screen selects taught back");check(ScreenPolicy.select(examples,"other.app",1080,2400,a,za)==-1,"other package waits");check(ScreenPolicy.select(examples,"target.app",2400,1080,a,za)==-1,"different resolution waits");check(ScreenPolicy.select(examples,"target.app",1080,2400,unknown,c.encode(unknown))==-1,"unknown image waits");examples.add(example(a,za,2));check(ScreenPolicy.select(examples,"target.app",1080,2400,a,za)==-1,"conflicting indistinguishable actions wait");examples.remove(2);check(ScreenPolicy.select(examples,"target.app",1080,2400,a,zb)==1,"circuit output actually drives candidate selection");Map<String,MarkerPlan.Point> live=new HashMap<>();live.put("A",new MarkerPlan.Point(100,200));live.put("B",new MarkerPlan.Point(300,400));String[] binding={"B","A"};MarkerPlan.Point[] resolved=MarkerPlan.resolve(binding,live);check(resolved[0].x==300&&resolved[1].x==100,"bound marker order preserved");live.put("B",new MarkerPlan.Point(500,600));check(MarkerPlan.resolve(binding,live)[0].x==500,"moving marker updates autonomous coordinates");live.remove("A");check(MarkerPlan.resolve(binding,live)==null,"deleted binding waits instead of stale tap");check(MarkerPlan.resolve(new String[0],live)==null,"empty marker group waits");examples.clear();ScreenPolicy.Example marker=example(a,za,4);marker.markerIds=new String[]{"B"};examples.add(marker);examples.add(example(b,zb,2));check(ScreenPolicy.select(examples,"target.app",1080,2400,a,za)==0,"known marker screen selects bound burst");check(ScreenPolicy.select(examples,"target.app",1080,2400,b,zb)==1,"next screen switches from markers to taught back");ScreenPolicy.Example conflict=example(a,za,4);conflict.markerIds=new String[]{"C"};examples.add(conflict);check(ScreenPolicy.select(examples,"target.app",1080,2400,a,za)==-1,"conflicting marker groups wait");examples.clear();ScreenPolicy.Example appA=example(a,za,4);appA.markerIds=new String[]{"A"};examples.add(appA);ScreenPolicy.Example appB=example(a,za,2);appB.pkg="second.app";examples.add(appB);check(ScreenPolicy.select(examples,"target.app",1080,2400,a,za)==0,"identical screen in first app uses its markers");check(ScreenPolicy.select(examples,"second.app",1080,2400,a,za)==1,"identical screen in second app uses its own back action");System.out.println("TOTAL "+checks+" checks passed. Synthetic policy checks; not a device UI benchmark.");
 }
 static void checkFinite(float v){if(!Float.isFinite(v))throw new AssertionError("nonfinite");}
}
